namespace CodexAutoProxyRepair {
 static class Program {
  [STAThread] static int Main(string[] args) {
   if(args.Length>0 && args[0]=="--self-test") {int t=L10n.SelfTest();if(t!=0)return 70+t;int p=ProxyConfig.SelfTest();if(p!=0)return 10+p;int l=RepairLedger.SelfTest();if(l!=0)return 30+l;int d=ToolDiagnostics.SelfTest();if(d!=0)return 50+d;return 0;}
   if(args.Length>0 && args[0]=="--scan") { try { string json=new JavaScriptSerializer().Serialize(Scanner.Run()); if(args.Length>1)File.WriteAllText(args[1],json,Encoding.UTF8);else Console.WriteLine(json);return 0;}catch{return 1;} }
   if(args.Length>0 && args[0]=="--diagnose") { try { string json=new JavaScriptSerializer().Serialize(ProxyConfig.Read()); if(args.Length>1)File.WriteAllText(args[1],json,Encoding.UTF8);else Console.WriteLine(json); return 0; } catch(Exception e){ if(args.Length>1)File.WriteAllText(args[1],new JavaScriptSerializer().Serialize(new {error=e.Message}),Encoding.UTF8);else Console.Error.WriteLine(e.Message); return 1; } }
   L10n.Initialize(); Application.EnableVisualStyles(); Application.SetCompatibleTextRenderingDefault(false); Application.Run(new MainForm()); return 0;
  }
 }
 class ScanResult { public string Proxy,Installed,Client,AppServer,Executor,Update; }
 static class Scanner {
  public static ScanResult Run(){var result=new ScanResult();ProxyConfig p=null;try{p=ProxyConfig.Read();result.Proxy="已启用手动代理：HTTP "+p.http+"；HTTPS "+p.https;}catch(Exception e){result.Proxy=e.Message;}result.Installed=MainForm.DetectInstall();result.AppServer=result.Executor="代理不可用，无法判断";try{result.Update=UpdateRepairForm.ReadLocalSummary();}catch{result.Update="更新状态未知";}
   string dir=Path.Combine(Path.GetTempPath(),"CodexScan-"+Guid.NewGuid().ToString("N"));bool owned=false;try{if(Directory.Exists(dir)||File.Exists(dir))throw new Exception();Directory.CreateDirectory(dir);owned=true;if((File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)throw new Exception();string path=Path.Combine(dir,"scan.ps1");using(var s=typeof(Program).Assembly.GetManifestResourceStream("CodexAutoProxyRepair.ScanHelper.ps1")){if(s==null)throw new Exception();using(var f=new FileStream(path,FileMode.CreateNew))s.CopyTo(f);}string b=Convert.ToBase64String(Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(p ?? new ProxyConfig())));string ps=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe");var si=new ProcessStartInfo(ps,"-NoProfile -NonInteractive -ExecutionPolicy Bypass -File \""+path+"\" -Payload "+b){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,StandardOutputEncoding=Encoding.UTF8};using(var proc=Process.Start(si)){string json=proc.StandardOutput.ReadToEnd();proc.WaitForExit();var data=new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(json);result.Client=data["client"];result.AppServer=data["app"];result.Executor=data["executor"];}}catch{result.Client=result.AppServer=result.Executor="未知（无法完成扫描）";}finally{try{if(owned&&Directory.Exists(dir)&&(File.GetAttributes(dir)&FileAttributes.ReparsePoint)==0)Directory.Delete(dir,true);}catch{}}return result;
  }
 }
 class ProxyConfig {
  [StructLayout(LayoutKind.Sequential)] struct IEConfig { public int AutoDetect; public IntPtr AutoConfigUrl, Proxy, ProxyBypass; }
  [DllImport("winhttp.dll",SetLastError=true)] static extern bool WinHttpGetIEProxyConfigForCurrentUser(out IEConfig c);
  [DllImport("kernel32.dll")] static extern IntPtr GlobalFree(IntPtr p);
  public string http {get;set;} public string https {get;set;}
  public static ProxyConfig Read() {
   IEConfig c; if(!WinHttpGetIEProxyConfigForCurrentUser(out c)) throw new Exception("无法读取 Windows 代理设置。");
   try { if(c.AutoDetect!=0 || c.AutoConfigUrl!=IntPtr.Zero) throw new Exception("检测到 PAC 或自动检测代理，暂不支持；请启用明确的手动系统代理。");
    using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Internet Settings")) { if(key==null || Convert.ToInt32(key.GetValue("ProxyEnable",0))!=1)throw new Exception("Windows 手动系统代理未启用，请先在代理软件中开启系统代理。"); }
    string s=Marshal.PtrToStringUni(c.Proxy); if(String.IsNullOrWhiteSpace(s)) throw new Exception("未检测到手动系统代理，请先在代理软件中开启系统代理。"); return Parse(s);
   } finally { if(c.AutoConfigUrl!=IntPtr.Zero)GlobalFree(c.AutoConfigUrl); if(c.Proxy!=IntPtr.Zero)GlobalFree(c.Proxy); if(c.ProxyBypass!=IntPtr.Zero)GlobalFree(c.ProxyBypass); }
  }
  static string Normalize(string raw) {
   if(String.IsNullOrWhiteSpace(raw)) throw new Exception("手动代理地址不完整。"); string s=raw.Trim(); if(!s.Contains("://"))s="http://"+s;
   Uri u; if(!Uri.TryCreate(s,UriKind.Absolute,out u) || u.Scheme!="http" || String.IsNullOrEmpty(u.Host) || !String.IsNullOrEmpty(u.UserInfo) || u.AbsolutePath!="/" || !String.IsNullOrEmpty(u.Query) || !String.IsNullOrEmpty(u.Fragment)) throw new Exception("代理须为不含账号密码、路径的 HTTP 地址。");
   string authority=s.Substring(s.IndexOf("://")+3).TrimEnd('/'); int colon=authority.LastIndexOf(':'); int port; if(colon<0 || !Int32.TryParse(authority.Substring(colon+1),out port) || port<1 || port>65535)throw new Exception("代理地址必须包含有效端口。");
   string host=u.Host.Trim('[',']'); if(u.HostNameType==UriHostNameType.IPv6 || host.IndexOf(':')>=0)host="["+IPAddress.Parse(host).ToString()+"]"; return "http://"+host+":"+port;
  }
  public static ProxyConfig Parse(string raw) { var m=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase); if(raw.IndexOf('=')>=0) { foreach(string part in raw.Split(';')) { int i=part.IndexOf('='); if(i<=0)throw new Exception("代理设置格式无效。"); if(i>0){string k=part.Substring(0,i).Trim().ToLowerInvariant(); if(k!="http" && k!="https")throw new Exception("不支持的代理协议。"); if(m.ContainsKey(k))throw new Exception("代理设置重复。");m[k]=part.Substring(i+1).Trim();} } } else {m["http"]=raw;m["https"]=raw;} if(!m.ContainsKey("http")||!m.ContainsKey("https"))throw new Exception("手动代理须同时提供 HTTP 和 HTTPS 地址。"); return new ProxyConfig {http=Normalize(m["http"]),https=Normalize(m["https"])}; }
  public static int SelfTest(){try{ if(Parse("127.0.0.1:7890").http!="http://127.0.0.1:7890")return 1; if(Parse("HTTP=localhost:80;HTTPS=localhost:80").http!="http://localhost:80")return 6; string v=Parse("http=localhost:8080;https=[::1]:8081").https; if(v!="http://[::1]:8081"){Console.Error.WriteLine("IPv6: "+v);return 2;} if(Parse("127.0.0.1:9999").https!="http://127.0.0.1:9999")return 3; foreach(string s in new[]{"http://u:p@host:88","host","socks5://host:88","host:70000","http=x:80","http=x:80;socks=y:90","http=x:80;garbage"}) {bool failed=false; try{Parse(s);}catch{failed=true;} if(!failed)return 4;} return 0;}catch{return 5;} }
 }
 class MainForm:Form {
  Label status=new Label(), recommendation=new Label(); ComboBox language=new ComboBox(); Button run=new Button(), dots=new Button(), update=new Button(), refresh=new Button(), help=new Button(), verify=new Button(), details=new Button(), export=new Button(); string selectedRepair="Codex 重连";
