  static readonly Color Canvas=ColorTranslator.FromHtml("#F4ECE3"), Surface=ColorTranslator.FromHtml("#F7F0E8"), Accent=ColorTranslator.FromHtml("#3354C8"), Ink=ColorTranslator.FromHtml("#292723"), Muted=ColorTranslator.FromHtml("#625C55");
  class SoftCard:Panel {
   public SoftCard(){DoubleBuffered=true;BackColor=Canvas;Padding=new Padding(18,14,18,17);AutoSize=true;AutoSizeMode=AutoSizeMode.GrowAndShrink;Margin=new Padding(0,0,0,12);}
   protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;Rectangle r=new Rectangle(2,2,Math.Max(1,Width-8),Math.Max(1,Height-8));using(var path=Rounded(r,14))using(var shadow=new SolidBrush(Color.FromArgb(220,208,195)))using(var fill=new SolidBrush(Surface))using(var pen=new Pen(Color.FromArgb(255,250,244))){e.Graphics.TranslateTransform(3,3);e.Graphics.FillPath(shadow,path);e.Graphics.TranslateTransform(-3,-3);e.Graphics.FillPath(fill,path);e.Graphics.DrawPath(pen,path);}}
   static GraphicsPath Rounded(Rectangle r,int d){var p=new GraphicsPath();p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
  }
  static void StyleButton(Button b,bool primary){b.AutoSize=true;b.MinimumSize=new Size(142,42);b.Padding=new Padding(12,6,12,6);b.FlatStyle=FlatStyle.Flat;b.FlatAppearance.BorderSize=primary?0:1;b.FlatAppearance.BorderColor=Color.FromArgb(211,201,191);b.BackColor=primary?Accent:Color.FromArgb(250,245,239);b.ForeColor=primary?Color.White:Ink;b.Font=new Font("Microsoft YaHei UI",10,FontStyle.Bold);b.Cursor=Cursors.Hand;b.UseVisualStyleBackColor=false;}
