  static void LimitWidth(Label label,int width){width=Math.Max(60,width);if(label.MaximumSize.Width!=width)label.MaximumSize=new Size(width,0);}
  static Control Card(string title,string description,Button action){var card=new SoftCard{Dock=DockStyle.Top};var table=new TableLayoutPanel{AutoSize=true,Dock=DockStyle.Fill,BackColor=Surface,ColumnCount=2};table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));table.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));var text=new FlowLayoutPanel{AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Dock=DockStyle.Fill,BackColor=Surface};var heading=TextLabel(title,12,FontStyle.Bold,Ink);var detail=TextLabel(description,9,FontStyle.Regular,Muted);text.Controls.Add(heading);text.Controls.Add(detail);table.Controls.Add(text,0,0);table.Controls.Add(action,1,0);action.Anchor=AnchorStyles.Right;card.Controls.Add(table);EventHandler wrap=(s,e)=>{int available=card.ClientSize.Width-card.Padding.Horizontal-Math.Max(action.Width,action.PreferredSize.Width)-34;LimitWidth(heading,available);LimitWidth(detail,available);};card.SizeChanged+=wrap;table.SizeChanged+=wrap;return card;}
  void ShowGuide(){using(var dialog=new Form{Text="使用引导",StartPosition=FormStartPosition.CenterParent,Size=new Size(560,390),MinimumSize=new Size(500,350),BackColor=Canvas,Font=Font,AutoScroll=true}){var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(28),BackColor=Canvas};flow.Controls.Add(TextLabel("三步开始",17,FontStyle.Bold,Ink));flow.Controls.Add(TextLabel("01  开启代理软件，并打开手动系统代理。",11,FontStyle.Bold,Ink));flow.Controls.Add(TextLabel("02  点击自动扫描，或按症状直接选择修复。",11,FontStyle.Bold,Ink));flow.Controls.Add(TextLabel("03  连接问题按提示正常退出后重开；更新修复仅在需要时请求 Windows 授权。",11,FontStyle.Bold,Ink));flow.Controls.Add(TextLabel("两种连接入口都让客户端及后台继承当前代理。一次实际排查中，单独升级未解决问题；继承代理后用户确认连接恢复。其他原因不一定适用。复检仅观察本机信号，仍需用真实消息和设备列表确认。PAC / 自动检测代理暂不支持。",9,FontStyle.Regular,Muted));var done=new Button{Text="知道了",DialogResult=DialogResult.OK};StyleButton(done,true);flow.Controls.Add(done);dialog.Controls.Add(flow);flow.SizeChanged+=(s,e)=>{int available=flow.ClientSize.Width-flow.Padding.Horizontal-24;foreach(Control item in flow.Controls){var label=item as Label;if(label!=null)LimitWidth(label,available);}};dialog.AcceptButton=done;L10n.Attach(dialog);dialog.ShowDialog(this);}}
  internal static string DetectInstall(){try{string command="$ProgressPreference='SilentlyContinue'; [Console]::OutputEncoding=New-Object Text.UTF8Encoding($false); $OutputEncoding=[Console]::OutputEncoding; $p=Get-AppxPackage -Name 'OpenAI.Codex' | Sort-Object {[version]$_.Version} -Descending | Select-Object -First 1; if($p -and $p.PackageFamilyName -ceq 'OpenAI.Codex_2p2nqsd0c76g0' -and $p.SignatureKind -eq 'Store' -and !$p.IsDevelopmentMode -and $p.Status -eq 'Ok') { Write-Output ('OK '+$p.Version) } else { Write-Output 'NOT_FOUND' }";string enc=Convert.ToBase64String(Encoding.Unicode.GetBytes(command));string ps=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe");string output=Compatibility.RunProbe(ps,"-NoProfile -NonInteractive -EncodedCommand "+enc);if(output==null)return "安装状态未知（检测超时或失败）";return output.StartsWith("OK ")?"已找到官方 Store 版 "+output.Substring(3):"未找到状态正常的官方 Store 版";}catch{return "检测失败，请检查 Windows PowerShell";}}
  public MainForm(){Text="Codex 自动代理修复";ClientSize=new Size(860,760);MinimumSize=new Size(640,560);StartPosition=FormStartPosition.CenterScreen;BackColor=Canvas;ForeColor=Ink;Font=new Font("Microsoft YaHei UI",10);AutoScroll=true;AutoScaleMode=AutoScaleMode.Font;
   var layout=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=1,Padding=new Padding(30,24,30,25),BackColor=Canvas};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));Controls.Add(layout);
   var languageRow=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Top,FlowDirection=FlowDirection.LeftToRight,WrapContents=false,BackColor=Canvas,Margin=new Padding(0,0,0,8)};var languageLabel=TextLabel("语言",9,FontStyle.Regular,Muted);languageLabel.Margin=new Padding(0,7,10,0);languageRow.Controls.Add(languageLabel);language.DropDownStyle=ComboBoxStyle.DropDownList;language.Width=150;language.Font=new Font("Microsoft YaHei UI",9);language.AccessibleName="Language";language.Items.AddRange(new object[]{"简体中文","繁體中文","English","日本語","한국어"});string[] languageCodes={"zh-CN","zh-TW","en","ja","ko"};language.SelectedIndex=Math.Max(0,Array.IndexOf(languageCodes,L10n.CurrentLanguage));language.SelectedIndexChanged+=(s,e)=>{if(language.SelectedIndex>=0)L10n.ChangeLanguage(languageCodes[language.SelectedIndex]);};languageRow.Controls.Add(language);layout.Controls.Add(languageRow);
   layout.Controls.Add(TextLabel("CODEX  ·  修复助手",9,FontStyle.Bold,Accent));layout.Controls.Add(TextLabel("让连接重新顺畅",21,FontStyle.Bold,Ink));var intro=TextLabel("针对部分代理继承与商店更新问题。先扫描，或直接选择下方功能。",10,FontStyle.Regular,Muted);intro.Margin=new Padding(0,2,0,16);layout.Controls.Add(intro);
   var actions=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Top,WrapContents=true,BackColor=Canvas,Margin=new Padding(0,0,0,12)}; refresh.Text="自动扫描检测";StyleButton(refresh,true);refresh.Click+=(s,e)=>Detect();actions.Controls.Add(refresh);verify.Text="修复后复检";StyleButton(verify,false);verify.Click+=(s,e)=>Verify(false);actions.Controls.Add(verify);help.Text="使用引导";StyleButton(help,false);help.Click+=(s,e)=>ShowGuide();actions.Controls.Add(help);export.Text="导出诊断";StyleButton(export,false);export.Click+=(s,e)=>ToolDiagnostics.ExportWithDialog(this);actions.Controls.Add(export);layout.Controls.Add(actions);
   var scanCard=new SoftCard{Dock=DockStyle.Top};var scanFlow=new FlowLayoutPanel{FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoSize=true,Dock=DockStyle.Fill,BackColor=Surface};scanFlow.Controls.Add(TextLabel("建议操作",11,FontStyle.Bold,Ink));recommendation.Text="先扫描，或按遇到的问题直接选择修复。";recommendation.AutoSize=true;recommendation.ForeColor=Ink;recommendation.BackColor=Color.Transparent;scanFlow.Controls.Add(recommendation);details.Text="查看技术详情";StyleButton(details,false);details.Click+=(s,e)=>{status.Visible=!status.Visible;details.Text=status.Visible?"收起技术详情":"查看技术详情";};scanFlow.Controls.Add(details);status.Text="尚未扫描。观察到代理连接不代表服务已恢复。";status.AutoSize=true;status.Visible=false;status.ForeColor=Muted;status.BackColor=Color.Transparent;status.Margin=new Padding(0,3,0,0);scanFlow.Controls.Add(status);scanCard.Controls.Add(scanFlow);scanCard.SizeChanged+=(s,e)=>{int available=scanCard.ClientSize.Width-scanCard.Padding.Horizontal-12;LimitWidth(status,available);LimitWidth(recommendation,available);};layout.Controls.Add(scanCard);
   layout.Controls.Add(TextLabel("选择需要修复的问题",12,FontStyle.Bold,Ink));
