  }
  void Busy(bool b){language.Enabled=!b;run.Enabled=!b;dots.Enabled=!b;update.Enabled=!b;refresh.Enabled=!b;verify.Enabled=!b;export.Enabled=!b;}
  static string Recommend(FullScan f){var d=f.Scan;if(f.Compatibility.Summary.IndexOf("缺少 Windows PowerShell")>=0)return "无法执行修复：未找到 Windows PowerShell。";if(f.Compatibility.Details.IndexOf("缺少 Appx 命令")>=0)return "无法验证或启动官方包：缺少 Appx 命令。";if(f.Compatibility.Details.IndexOf("清单状态未知")>=0)return "官方包清单状态未知，暂不能确认启动条件；请展开技术详情。";if(!d.Proxy.StartsWith("已启用"))return "先检查代理设置："+d.Proxy;if(!d.Installed.StartsWith("已找到"))return "先检查官方安装："+d.Installed;if(d.AppServer.IndexOf("未观察到")>=0||d.Executor.IndexOf("未观察到")>=0)return "建议按症状选择连接修复：有后台进程未观察到当前代理连接，但也可能只是空闲。";if(f.Verification.RecentRetryCount>0)return "建议检查 Codex 重连：客户端启动后记录了重试；请先确认网络状况。";if(f.Verification.DotsState.IndexOf("失败")>=0)return "建议检查 Dots 连接：当前启动期间观察到握手失败。";return "暂未发现可确定的代理继承故障。请按症状选择功能，并用真实消息和设备列表确认。";}
  void Detect(){Busy(true);recommendation.Text="正在扫描当前代理、安装和相关进程…";var w=new BackgroundWorker();w.DoWork+=(s,e)=>{e.Result=new FullScan{Scan=Scanner.Run(),Compatibility=Compatibility.Check(),Verification=ServiceVerification.Run()};};w.RunWorkerCompleted+=(s,e)=>{if(IsDisposed||Disposing)return;if(e.Error!=null)recommendation.Text="扫描失败，请检查系统权限。";else{var f=(FullScan)e.Result;var d=f.Scan;recommendation.Text=Recommend(f);status.Text="代理："+d.Proxy+"\n安装："+d.Installed+"\n客户端："+d.Client+"\nCodex 后台："+d.AppServer+"\nDots 执行器："+d.Executor+"\n更新："+d.Update+"\n兼容性："+f.Compatibility.Summary+"；"+f.Compatibility.Details+"\n对话复检："+f.Verification.CodexState+"\nDots 复检："+f.Verification.DotsState+"\n"+f.Verification.Details;}Busy(false);};w.RunWorkerAsync();}
  void Verify(bool afterLaunch){Busy(true);recommendation.Text=afterLaunch?"正在等待启动后的设备信号（最多45秒）…":"正在复检当前启动后的本机信号…";var w=new BackgroundWorker();w.DoWork+=(s,e)=>{e.Result=afterLaunch?ServiceVerification.WaitForSignals():ServiceVerification.Run();};w.RunWorkerCompleted+=(s,e)=>{if(IsDisposed||Disposing)return;if(e.Error!=null)recommendation.Text="复检状态未知，请用真实消息和设备列表确认。";else{var r=(VerificationReport)e.Result;recommendation.Text=r.Summary+"\n对话："+r.CodexState+"\nDots："+r.DotsState;status.Text=r.Details+(r.RecentRetryCount>=0?"\n本机近5分钟重试记录："+r.RecentRetryCount:"\n重试记录：未知");}Busy(false);};w.RunWorkerAsync();}
  void Launch(){Busy(true);recommendation.Text="正在验证并启动…";var w=new BackgroundWorker();w.DoWork+=(s,e)=>{string dir=null;bool ownDir=false;using(var gate=new Mutex(false,@"Local\CodexAutoProxyRepairLaunch")){bool held=false;try{held=gate.WaitOne(0);if(!held)throw new Exception("另一个修复窗口正在启动，请稍候。");var p=ProxyConfig.Read();dir=Path.Combine(Path.GetTempPath(),"CodexAutoProxy-"+Guid.NewGuid().ToString("N"));if(Directory.Exists(dir)||File.Exists(dir))throw new Exception("临时目录冲突。");Directory.CreateDirectory(dir);ownDir=true;if((File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)throw new Exception("临时目录不可用。");string script=Path.Combine(dir,"helper.ps1");using(var stream=typeof(Program).Assembly.GetManifestResourceStream("CodexAutoProxyRepair.LaunchHelper.ps1")){if(stream==null)throw new Exception("启动组件缺失。");using(var f=new FileStream(script,FileMode.CreateNew))stream.CopyTo(f);}string payload=Convert.ToBase64String(Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(p ?? new ProxyConfig())));string ps=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe");var si=new ProcessStartInfo(ps,"-NoProfile -NonInteractive -ExecutionPolicy Bypass -File \""+script+"\" -Payload "+payload){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};using(var proc=Process.Start(si)){string output=proc.StandardOutput.ReadToEnd();string err=proc.StandardError.ReadToEnd();proc.WaitForExit();e.Result=proc.ExitCode==0?"已让客户端继承当前代理启动。请检查"+selectedRepair+"是否恢复；Dots 需已有配对设备。":"启动未完成："+(String.IsNullOrWhiteSpace(output)?"请确认 Codex 已正常退出并检查安装。":output.Trim());}}catch(Exception x){e.Result="启动未完成："+x.Message;}finally{try{if(ownDir && dir!=null && Path.GetFullPath(dir).StartsWith(Path.GetFullPath(Path.GetTempPath()),StringComparison.OrdinalIgnoreCase) && Directory.Exists(dir) && (File.GetAttributes(dir)&FileAttributes.ReparsePoint)==0)Directory.Delete(dir,true);}catch{} if(held)gate.ReleaseMutex();}}};w.RunWorkerCompleted+=(s,e)=>{if(IsDisposed||Disposing)return;string result=e.Error!=null?"启动状态未知，请检查客户端。":(string)e.Result;recommendation.Text=result;Busy(false);if(result.StartsWith("已让客户端"))Verify(true);};w.RunWorkerAsync();}
